const price = Number($json.price);
const prev = Number($json.previous_price);

let anomaly = "";
let status = "OK"; // default

if (!price) {
  anomaly = "Missing Value";
  status = "FLAGGED";
} else if (prev && prev !== 0) {
  const change = (price - prev) / prev;

  if (change > 0.2) {
    anomaly = "Sudden Spike";
    status = "FLAGGED";
  } else if (change < -0.2) {
    anomaly = "Sudden Drop";
    status = "FLAGGED";
  }
}

return [{ ...$json, anomaly, status }];

